import torch
from collections import deque
from dataclasses import dataclass
from typing import List

@dataclass
class FrameToken:
    tokens: torch.Tensor  # (num_tokens, hidden_dim)
    timestamp: float

class StreamingMemory:
    def __init__(self, spatial_cap=32, temporal_cap=64,
                 abstract_cap=32):
        self.spatial = deque(maxlen=spatial_cap)   # recent, detail
        self.temporal = deque(maxlen=temporal_cap) # dynamic, mid
        self.abstract = deque(maxlen=abstract_cap) # long, summary

    def add(self, frame_tokens, ts):
        # transition oldest spatial → temporal (compressed)
        if len(self.spatial) == self.spatial.maxlen:
            old = self.spatial[0]
            compressed = self._compress(old, ratio=4)
            self.temporal.append(compressed)
        self.spatial.append(FrameToken(frame_tokens, ts))

    def consolidate_to_abstract(self):
        # batch-distill recent temporal into abstract summary
        if len(self.temporal) >= 16:
            batch = list(self.temporal)[:16]
            summary = self._distill(batch, output_tokens=8)
            self.abstract.append(summary)
            # remove distilled from temporal
            for _ in range(16):
                self.temporal.popleft()

    def get_context(self, query=None):
        # query-aware retrieval (skipped for brevity)
        ctx = []
        for f in self.abstract:
            ctx.append(f.tokens)
        for f in self.temporal:
            ctx.append(f.tokens)
        for f in self.spatial:
            ctx.append(f.tokens)
        return torch.cat(ctx, dim=0)

    def _compress(self, frame, ratio):
        # mean pooling - production uses learned Q-Former
        t = frame.tokens
        n = t.shape[0] // ratio
        return FrameToken(t[:n*ratio].view(n, ratio, -1).mean(1),
                          frame.timestamp)

    def _distill(self, frames, output_tokens):
        all_tokens = torch.cat([f.tokens for f in frames], dim=0)
        idx = torch.linspace(0, all_tokens.shape[0]-1,
                             output_tokens).long()
        return FrameToken(all_tokens[idx], frames[-1].timestamp)

import time
import torch
import numpy as np
from collections import deque, defaultdict
from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class StageProfile:
    samples: deque = field(default_factory=lambda: deque(maxlen=10000))

    def add(self, ms: float):
        self.samples.append(ms)

    def percentiles(self) -> dict:
        if not self.samples:
            return {"p50": 0, "p95": 0, "p99": 0}
        arr = np.fromiter(self.samples, dtype=np.float64)
        return {
            "p50": float(np.percentile(arr, 50)),
            "p95": float(np.percentile(arr, 95)),
            "p99": float(np.percentile(arr, 99)),
        }

class PipelineProfiler:
    STAGES = ["capture", "decode", "sample", "encode",
              "reduce", "llm_prefill", "llm_decode", "response"]

    def __init__(self, sample_rate: float = 0.01):
        self.profiles = {s: StageProfile() for s in self.STAGES}
        self.sample_rate = sample_rate  # only profile 1% of frames

    @contextmanager
    def stage_cpu(self, name: str, frame_id: int):
        # CPU/host-side stage timing.
        if not self._should_sample(frame_id):
            yield; return
        t0 = time.perf_counter()
        yield
        dt = (time.perf_counter() - t0) * 1000.0
        self.profiles[name].add(dt)

    @contextmanager
    def stage_gpu(self, name: str, frame_id: int):
        # GPU stage timing via CUDA events (wall-clock would lie).
        if not self._should_sample(frame_id):
            yield; return
        start = torch.cuda.Event(enable_timing=True)
        end = torch.cuda.Event(enable_timing=True)
        start.record()
        yield
        end.record()
        end.synchronize()
        self.profiles[name].add(start.elapsed_time(end))

    def _should_sample(self, frame_id: int) -> bool:
        return (frame_id * 2654435761 & 0xFFFFFFFF) / 2**32 < self.sample_rate

    def report(self) -> dict:
        return {s: self.profiles[s].percentiles() for s in self.STAGES}

    def critical_path_p99(self) -> float:
        return sum(self.profiles[s].percentiles()["p99"] for s in self.STAGES)

    def amdahl_speedup(self, stage: str, factor: float) -> float:
        total = sum(self.profiles[s].percentiles()["p99"] for s in self.STAGES)
        stage_t = self.profiles[stage].percentiles()["p99"]
        f = stage_t / total if total > 0 else 0
        return 1.0 / ((1 - f) + f / factor)
